<script setup lang="ts">import type {Profile} from '../types/domain';import {pct} from '../utils/format';defineProps<{profile:Profile}>()</script><template><section class="topic-terms"><header><small>TOPIC {{String(profile.topic_index+1).padStart(2,'0')}} / H 行L1词权</small><h2>{{profile.label}}</h2><p>人工命名；词权只作编辑线索。</p></header><div class="term-row" v-for="(word,i) in profile.weights.slice(0,10)" :key="word.term"><small>{{String(i+1).padStart(2,'0')}}</small><span>{{word.term}}</span><div><i :style="{width:(word.weight/(profile.weights[0]?.weight||1)*100)+'%'}"/></div><b>{{pct(word.weight)}}</b></div></section></template>
